package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.io.*;
import javax.imageio.ImageIO;
import static org.junit.Assert.*;

public class TabletopStoreTest {
    static JSONObject frame(int ordinal)throws Exception{var out=new ByteArrayOutputStream();ImageIO.write(TabletopCoreTest.image(Math.min(ordinal,8),0,false),"png",out);byte[] b=out.toByteArray();return new JSONObject().put("image",Base64.getEncoder().encodeToString(b)).put("imageSha256",PerceptionStore.hash(b)).put("seconds",ordinal*.2);}
    static JSONObject definition(){return PlaneCalibrationTest.mat().put("imagePoints",new JSONArray("[[0.2,0.25],[0.8,0.25],[0.8,0.75],[0.2,0.75]]"));}
    static JSONObject args(WorldLedger ledger,String world,String geometry,String check)throws Exception{var n=ledger.observe(world);return new JSONObject().put("worldId",world).put("expectedRevision",n.getInt("expectedRevision")).put("expectedHash",n.getString("expectedHash")).put("geometryId",geometry).put("checkId",check).put("cameraKey","test-fixed").put("bodyId",n.getJSONObject("frame").getJSONArray("bodies").getJSONObject(0).getString("id")).put("label","labelled analytic rigid target").put("box",TabletopCoreTest.box().json()).put("frame",frame(0));}
    static JSONObject check(TabletopStore s,String g)throws Exception{return s.check(new JSONObject().put("geometryId",g).put("cameraKey","test-fixed").put("frame",frame(0)).put("pointA",new JSONArray("[0.3,0.3]")).put("pointB",new JSONArray("[0.3,0.6]")).put("lengthM",.18288).put("markA",2).put("markB",9.2).put("unit","in").put("source","Labelled analytic geometric control, not a physical tape measurement"));}
    static JSONObject upload(TabletopStore s,JSONObject r,int i)throws Exception{return s.frame(new JSONObject().put("id",r.getString("id")).put("generation",r.getInt("generation")).put("cameraKey","test-fixed").put("ordinal",i).put("frame",frame(i)));}
    @Test public void actualProcessingStopGenerationsRestartPrefixAndIndependentAnalysis()throws Exception{
        Path root=Files.createTempDirectory("tabletop038-journal-");var ledger=new WorldLedger(root);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Tabletop analytic test").getString("id");
        try(var o=new WorldObservationStore(root,ledger)){var m=new MetricObservationStore(root,o,ledger);String g=m.geometry(definition()).getString("id");var s=new TabletopStore(root,ledger,m);var c=check(s,g);assertTrue(c.toString(),c.getBoolean("passed"));assertEquals(.18288,c.getDouble("measuredM"),1e-10);assertThrows(IllegalStateException.class,()->check(s,g));var nativeState=ledger.observe(world);var r=s.start(args(ledger,world,g,c.getString("id")));for(int i=1;i<=6;i++)upload(s,r,i);var prefix=s.read(r.getString("id")).getJSONArray("trace");s.stop(r.getString("id"));var stoppedRun=r;assertThrows(IllegalStateException.class,()->upload(s,stoppedRun,7));r=s.resume(r.getString("id"));upload(s,r,7);
            var restarted=new TabletopStore(root,ledger,m);assertEquals("interrupted",restarted.read(r.getString("id")).getString("status"));r=restarted.resume(r.getString("id"));for(int i=8;i<=16;i++)upload(restarted,r,i);restarted.finish(r.getString("id"));var done=restarted.read(r.getString("id"));for(int i=0;i<prefix.length();i++)assertTrue(prefix.getJSONObject(i).similar(done.getJSONArray("trace").getJSONObject(i)));assertEquals(16,done.getInt("completedFrames"));assertTrue(nativeState.similar(ledger.observe(world)));assertEquals("completed",done.getString("status"));var report=TabletopReport.build(done,restarted.understanding(done.getString("id")),restarted.analyses(done.getString("id")));assertFalse(report.getJSONObject("files").getString("index.html").contains("data:image"));assertEquals(16,new JSONObject(report.getJSONObject("files").getString("tabletop-data.json")).getJSONArray("rows").length());var export=restarted.export(done.getString("id"));assertEquals(17,export.getJSONArray("images").length());
            var move=restarted.analyse(new JSONObject().put("id",done.getString("id")).put("kind","displacement").put("fromMark",4).put("toMark",8).put("source","Negative analytic test: actual short movement is not the declared4in"));assertFalse(move.getBoolean("passed"));assertThrows(IllegalStateException.class,()->restarted.analyse(new JSONObject().put("id",done.getString("id")).put("kind","displacement").put("fromMark",4).put("toMark",8).put("source","do not overwrite first result")));
            var refs=new JSONArray();var plane=new PlaneCalibration(definition());for(int i=1;i<=12;i++)refs.put(new JSONObject().put("ordinal",i).put("positionM",new JSONArray(plane.project((114+Math.min(i,8))/320.,95./240))));var fit=restarted.analyse(new JSONObject().put("id",done.getString("id")).put("kind","fit").put("references",refs).put("source","Independent analytic source coordinates from known rendered target, not tracker output"));assertTrue(fit.getDouble("multiplier")>=.1);assertThrows(IllegalArgumentException.class,()->restarted.analyse(new JSONObject().put("id",done.getString("id")).put("kind","evaluate").put("references",refs).put("profileId",fit.getString("id")).put("source","same-run refused")));
        }
    }
    @Test public void cameraClockChecksumAndUnmeasuredScaleCannotBeInvented()throws Exception{
        Path root=Files.createTempDirectory("tabletop038-guards-");var ledger=new WorldLedger(root);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Guards").getString("id");try(var o=new WorldObservationStore(root,ledger)){var m=new MetricObservationStore(root,o,ledger);var s=new TabletopStore(root,ledger,m);String g=m.geometry(definition()).getString("id");var c=check(s,g);var r=s.start(args(ledger,world,g,c.getString("id")));var wrong=new JSONObject().put("id",r.getString("id")).put("generation",0).put("cameraKey","other-camera").put("ordinal",1).put("frame",frame(1));assertThrows(IllegalArgumentException.class,()->s.frame(wrong));wrong.put("cameraKey","test-fixed").getJSONObject("frame").put("imageSha256","0".repeat(64));assertThrows(IllegalStateException.class,()->s.frame(wrong));assertEquals(0,s.read(r.getString("id")).getInt("completedFrames"));upload(s,r,1);var backwards=new JSONObject().put("id",r.getString("id")).put("generation",0).put("cameraKey","test-fixed").put("ordinal",2).put("frame",frame(2).put("seconds",.1));assertThrows(IllegalArgumentException.class,()->s.frame(backwards));assertEquals("interrupted",s.read(r.getString("id")).getString("status"));assertEquals(1,s.read(r.getString("id")).getInt("completedFrames"));}
    }
}
